using Microsoft.AspNetCore.Mvc;using PokeMarketApi.Services;namespace PokeMarketApi.Controllers;public class SearchController(CatalogClient c):Controller{public async Task<IActionResult> Index(string? q,string? setName,string? language){try{var a=await c.GetCards();if(!string.IsNullOrWhiteSpace(q))a=a.Where(x=>x.Name.Contains(q,StringComparison.OrdinalIgnoreCase)||x.CardNumber.Contains(q,StringComparison.OrdinalIgnoreCase)).ToList();if(!string.IsNullOrWhiteSpace(setName))a=a.Where(x=>x.SetName==setName).ToList();if(!string.IsNullOrWhiteSpace(language))a=a.Where(x=>x.Language==language).ToList();ViewBag.Sets=await c.GetSets();return View(a);}catch{ViewBag.Sets=new List<string>();ViewBag.Offline=true;return View(new List<CatalogCard>());}}}